const update = $json;

// 1. Callback query (кнопки врача)
if (update.callback_query?.data) {
  return {
    input_type: 'callback',
    callback_data: update.callback_query.data,
    callback_id: update.callback_query.id,
    message_id: update.callback_query.message?.message_id || '',
    chat_id: String(update.callback_query.from?.id || ''),
    user_name: [
      update.callback_query.from?.first_name || '',
      update.callback_query.from?.last_name || ''
    ].filter(Boolean).join(' '),
    username: update.callback_query.from?.username || ''
  };
}

const msg = update.message;
if (!msg) {
  return { input_type: 'fallback', chat_id: '', user_name: '', username: '' };
}

const chat_id = String(msg.from?.id || msg.chat?.id || '');
const user_name = [
  msg.from?.first_name || '',
  msg.from?.last_name || ''
].filter(Boolean).join(' ');
const username = msg.from?.username || '';

// 2. Voice
if (msg.voice) {
  return {
    input_type: 'voice',
    chat_id, user_name, username,
    file_id: msg.voice.file_id,
    duration: msg.voice.duration
  };
}

// 3. Photo
if (msg.photo && msg.photo.length > 0) {
  const bestPhoto = msg.photo[msg.photo.length - 1];
  return {
    input_type: 'photo',
    chat_id, user_name, username,
    file_id: bestPhoto.file_id,
    caption: msg.caption || ''
  };
}

// 4. Text
if (msg.text) {
  return {
    input_type: 'text',
    chat_id, user_name, username,
    text: msg.text
  };
}

// 5. Fallback
return { input_type: 'fallback', chat_id, user_name, username };

const checkInput = $('Check Input Type').first().json;

// Определяем источник текста: voice, photo или text
let text = '';
let chat_id = checkInput.chat_id || '';
let user_name = checkInput.user_name || '';
let username = checkInput.username || '';
let voice_used = 'FALSE';
let photo_analysis = '';

// Пробуем Voice
try {
  const voice = $('Set Unified Format Voice').first().json;
  if (voice && voice.text) {
    text = voice.text;
    chat_id = voice.chat_id;
    user_name = voice.user_name;
    username = voice.username;
    voice_used = voice.voice_used || 'TRUE';
  }
} catch(e) {}

// Пробуем Photo
try {
  const photo = $('Set Unified Format Photo').first().json;
  if (photo && photo.text) {
    text = photo.text;
    chat_id = photo.chat_id;
    user_name = photo.user_name;
    username = photo.username;
    photo_analysis = photo.photo_analysis || '';
  }
} catch(e) {}

// Если ни voice, ни photo — берём из Check Input Type (обычный текст)
if (!text) {
  text = checkInput.text || '';
}

// Проверяем doctor pending
const doctorRows = $('Check Doctor Pending').all();
const doctor = doctorRows.find(
  r => r.json.telegram_id && r.json.doctor_pending_inquiry_id
);

if (doctor && text.trim().toLowerCase() !== '/start') {
  return {
    route: 'doctor_question',
    doctor_id: doctor.json.doctor_id,
    doctor_name: doctor.json.name,
    pending_inquiry_id: doctor.json.doctor_pending_inquiry_id,
    question_text: text,
    chat_id: chat_id,
    user_name: user_name,
    username: username
  };
}

const isStart = text.trim().toLowerCase() === '/start';

return {
  route: isStart ? 'start' : 'message',
  text: text,
  chat_id: chat_id,
  user_name: user_name,
  username: username,
  voice_used: voice_used,
  photo_analysis: photo_analysis
};

const input = $('Route: Doctor or Patient').first().json;
const inquiryRows = $('Lookup Returning Patient').all();
const validInquiries = inquiryRows.filter(
  r => r.json.inquiry_id && r.json.inquiry_id !== ''
);
const isReturning = validInquiries.length > 0;

const now = new Date().toISOString();
const sessionId = 'SES-' + now.replace(/\D/g, '').slice(0, 12);

let previousSummary = '';
if (isReturning) {
  previousSummary = validInquiries
    .slice(-3)
    .map(r => `${r.json.date}: ${r.json.direction} — ${r.json.summary}`)
    .join('\n');
}

return {
  session_id: sessionId,
  telegram_user_id: input.chat_id,
  client_name: input.user_name,
  client_username: input.username ? '@' + input.username : '',
  language: '',
  stage: 'awaiting_complaint',
  collected_data: '{}',
  awaiting_doctor_response: '',
  doctor_question_for_patient: '',
  created_at: now,
  updated_at: now,
  is_returning: isReturning,
  previous_summary: previousSummary,
  previous_inquiry_ids: validInquiries
    .map(r => r.json.inquiry_id).join(', ')
};

const input = $('Route: Doctor or Patient').first().json;
const sessions = $('Lookup Session').all();

// Ищем активную сессию (не completed, не emergency, не closed)
const active = sessions.find(r => {
  const stage = (r.json.stage || '').toLowerCase();
  return r.json.session_id &&
    stage !== 'completed' &&
    stage !== 'emergency' &&
    stage !== 'closed_by_new_start';
});

if (!active) {
  return {
    has_session: false,
    chat_id: input.chat_id,
    text: input.text
  };
}

return {
  has_session: true,
  session_id: active.json.session_id,
  stage: active.json.stage,
  collected_data: active.json.collected_data || '{}',
  language: active.json.language || '',
  client_name: active.json.client_name || '',
  chat_id: input.chat_id,
  text: input.text,
  voice_used: input.voice_used || 'FALSE',
  photo_analysis: input.photo_analysis || ''
};

const session = $('Find Active Session').first().json;
const input = $('Route: Doctor or Patient').first().json;
const servicesRows = $('Get RAG Services').all();

// Собираем справочник услуг для RAG
const services = servicesRows
  .filter(r => r.json.service_id)
  .map(r => `${r.json.direction}: ${r.json.service_name} — ${r.json.description}`)
  .join('\n');

// Парсим собранные данные
let collected = {};
try {
  collected = JSON.parse(session.collected_data || '{}');
} catch(e) {
  collected = {};
}

// Считаем раунды уточнений
const clarificationCount = collected.clarification_count || 0;
const maxClarifications = 5;
const forceComplete = clarificationCount >= maxClarifications;

// Добавляем новое сообщение
if (session.stage === 'awaiting_complaint') {
  collected.complaint = input.text;
  if (input.photo_analysis) {
    collected.photo_analysis = input.photo_analysis;
  }
} else {
  // gathering_details — добавляем ответ на уточнение
  collected[`clarification_${clarificationCount}`] = input.text;
  if (input.photo_analysis) {
    collected[`photo_analysis_${clarificationCount}`] = input.photo_analysis;
  }
}
collected.clarification_count = clarificationCount + (session.stage === 'gathering_details' ? 1 : 0);

// Формируем историю диалога для LLM
const collectedText = Object.entries(collected)
  .filter(([k, v]) => k !== 'clarification_count' && v)
  .map(([k, v]) => `${k}: ${v}`)
  .join('\n');

const systemPrompt = `Ты — медицинский ассистент-интервьюер клиники «НоваМед». Твоя задача — собрать информацию о жалобе пациента для врача.

ПРАВИЛА:
1. Ты НЕ врач и НЕ ставишь диагнозов. Только собираешь информацию.
2. Общайся вежливо, спокойно, на языке пациента.
3. Определи язык пациента по первому сообщению и веди диалог на нём.

ОБЯЗАТЕЛЬНЫЕ ПОЛЯ для сбора:
- Основная жалоба (что беспокоит)
- Локализация (где именно)
- Длительность (как давно)
- Интенсивность (по шкале 1-10 или словами)
- Сопутствующие симптомы
- Хронические заболевания / аллергии
- Возраст пациента (или возраст ребёнка, если обращение по поводу ребёнка)

ЭКСТРЕННЫЕ СИМПТОМЫ — если пациент описывает ЛЮБОЙ из следующих, НЕМЕДЛЕННО установи is_emergency = true:
- Сильная боль в груди с одышкой
- Потеря сознания
- Сильное кровотечение, которое не останавливается
- Затруднённое дыхание / удушье
- Внезапная слабость одной стороны тела, нарушение речи (признаки инсульта)
- Судороги
- Тяжёлая аллергическая реакция (отёк горла, невозможность дышать)

СПРАВОЧНИК УСЛУГ КЛИНИКИ:
${services}

СОБРАННЫЕ ДАННЫЕ НА ДАННЫЙ МОМЕНТ:
${collectedText || 'Пока ничего не собрано — это первое сообщение пациента.'}

${forceComplete ? 'ВНИМАНИЕ: Достигнут лимит уточнений. Заверши сбор с тем, что есть. Установи is_sufficient = true.' : ''}

ОТВЕТЬ СТРОГО В JSON:
{
  "is_emergency": true/false,
  "emergency_description": "описание экстренной ситуации (только если is_emergency=true)",
  "is_sufficient": true/false,
  "detected_language": "ru/en/другой код языка",
  "next_question": "следующий уточняющий вопрос для пациента (только если is_sufficient=false и is_emergency=false)",
  "direction_hint": "предварительное направление (cardiology/neurology/pediatrics/и т.д.) если уже понятно, иначе пустая строка"
}`;

const requestBody = {
  model: 'deepseek-v4-flash',
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: input.text }
  ],
  temperature: 0.3
};

return {
  request_body: JSON.stringify(requestBody),
  collected_data: JSON.stringify(collected),
  session_id: session.session_id,
  chat_id: session.chat_id,
  client_name: session.client_name,
  voice_used: input.voice_used || 'FALSE',
  photo_analysis: input.photo_analysis || ''
};

const prev = $('Build Interviewer Prompt').first().json;
let content = $json.choices[0].message.content;

// Чистим markdown обёртку если есть
content = content.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(content);
} catch(e) {
  // Если JSON обрезан — пробуем починить
  try {
    if (!content.endsWith('}')) content += '}';
    parsed = JSON.parse(content);
  } catch(e2) {
    parsed = {
      is_emergency: false,
      is_sufficient: false,
      detected_language: 'ru',
      next_question: 'Пожалуйста, расскажите подробнее о вашей жалобе.',
      direction_hint: ''
    };
  }
}

return {
  is_emergency: parsed.is_emergency || false,
  emergency_description: parsed.emergency_description || '',
  is_sufficient: parsed.is_sufficient || false,
  detected_language: parsed.detected_language || 'ru',
  next_question: parsed.next_question || '',
  direction_hint: parsed.direction_hint || '',
  collected_data: prev.collected_data,
  session_id: prev.session_id,
  chat_id: prev.chat_id,
  client_name: prev.client_name,
  voice_used: prev.voice_used,
  photo_analysis: prev.photo_analysis
};

const parsed = $('Parse Interviewer Response').first().json;
const session = $('Find Active Session').first().json;

const text = `🚨 ЭКСТРЕННОЕ ОБРАЩЕНИЕ\n\n` +
  `Пациент: ${session.client_name}\n` +
  `Telegram: @${(session.chat_id)}\n` +
  `Описание: ${parsed.emergency_description}\n\n` +
  `Собранные данные:\n${parsed.collected_data}\n\n` +
  `Пациенту рекомендовано вызвать скорую (103).`;

return {
  text: text,
  admin_chat_id: '448587092'
};

const prev = $('Parse Interviewer Response').first().json;
const servicesRows = $('Get RAG Services').all();

const services = servicesRows
  .filter(r => r.json.service_id)
  .map(r => `${r.json.direction}: ${r.json.service_name} — ${r.json.description}`)
  .join('\n');

const systemPrompt = `Ты — медицинский аналитик клиники «НоваМед». На основе собранных данных пациента сформируй структурированную карту для врача.

СОБРАННЫЕ ДАННЫЕ:
${prev.collected_data}

СПРАВОЧНИК НАПРАВЛЕНИЙ КЛИНИКИ:
${services}

ДОСТУПНЫЕ НАПРАВЛЕНИЯ (выбери ОДНО основное):
cardiology, neurology, dermatology, allergology, gastroenterology, surgery, urology, pediatrics, therapy

ОТВЕТЬ СТРОГО В JSON:
{
  "direction": "одно из направлений выше",
  "urgency": "low / medium / high",
  "severity": "mild / moderate / severe",
  "summary": "краткое описание ситуации для врача (2-3 предложения)",
  "key_symptoms": "перечисление основных симптомов через запятую",
  "attention_points": "на что врачу обратить особое внимание",
  "recommended_tests": "рекомендуемые анализы/обследования из справочника клиники"
}`;

const requestBody = {
  model: 'deepseek-v4-flash',
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: 'Сформируй карту пациента.' }
  ],
  temperature: 0.2
};

return {
  request_body: JSON.stringify(requestBody),
  session_id: prev.session_id,
  chat_id: prev.chat_id,
  client_name: prev.client_name,
  collected_data: prev.collected_data,
  detected_language: prev.detected_language,
  voice_used: prev.voice_used,
  photo_analysis: prev.photo_analysis
};

const prev = $('Build Final Analysis Prompt').first().json;
let content = $json.choices[0].message.content;
content = content.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(content);
} catch(e) {
  try {
    if (!content.endsWith('}')) content += '}';
    parsed = JSON.parse(content);
  } catch(e2) {
    parsed = {
      direction: 'therapy',
      urgency: 'medium',
      severity: 'moderate',
      summary: 'Не удалось провести автоматический анализ. Требуется ручной разбор.',
      key_symptoms: '',
      attention_points: '',
      recommended_tests: ''
    };
  }
}

const now = new Date().toISOString();
const inquiryId = 'INQ-' + now.replace(/\D/g, '').slice(0, 12);

return {
  inquiry_id: inquiryId,
  date: now.slice(0, 10),
  session_id: prev.session_id,
  client_name: prev.client_name,
  client_telegram_id: prev.chat_id,
  language: prev.detected_language,
  direction: parsed.direction || 'therapy',
  urgency: parsed.urgency || 'medium',
  severity: parsed.severity || 'moderate',
  summary: parsed.summary || '',
  key_symptoms: parsed.key_symptoms || '',
  attention_points: parsed.attention_points || '',
  recommended_tests: parsed.recommended_tests || '',
  original_text: prev.collected_data,
  photo_analysis: prev.photo_analysis || '',
  voice_used: prev.voice_used || 'FALSE',
  chat_id: prev.chat_id
};

const inquiry = $('Parse Final Analysis').first().json;
const doctors = $('Get Doctors').all();

const direction = inquiry.direction;

// Фильтруем: активен + специализация содержит direction + не перегружен
const candidates = doctors
  .filter(r => {
    if (!r.json.doctor_id || r.json.status !== 'active') return false;
    const specs = (r.json.specializations || '').split(',').map(s => s.trim());
    return specs.includes(direction);
  })
  .filter(r => {
    const active = parseInt(r.json.active_patients) || 0;
    const max = parseInt(r.json.max_patients) || 999;
    return active < max;
  })
  .sort((a, b) => {
    const aLoad = (parseInt(a.json.active_patients) || 0) / (parseInt(a.json.max_patients) || 1);
    const bLoad = (parseInt(b.json.active_patients) || 0) / (parseInt(b.json.max_patients) || 1);
    return aLoad - bLoad;
  });

// Fallback — любой доступный врач
let matched = candidates[0] || null;
if (!matched) {
  const fallback = doctors
    .filter(r => r.json.doctor_id && r.json.status === 'active')
    .filter(r => (parseInt(r.json.active_patients) || 0) < (parseInt(r.json.max_patients) || 999))
    .sort((a, b) => (parseInt(a.json.active_patients) || 0) - (parseInt(b.json.active_patients) || 0));
  matched = fallback[0] || null;
}

if (!matched) {
  return {
    found_doctor: false,
    inquiry_id: inquiry.inquiry_id,
    chat_id: inquiry.chat_id
  };
}

return {
  found_doctor: true,
  doctor_id: matched.json.doctor_id,
  doctor_name: matched.json.name,
  doctor_telegram_id: matched.json.telegram_id,
  inquiry_id: inquiry.inquiry_id,
  direction: inquiry.direction,
  urgency: inquiry.urgency,
  severity: inquiry.severity,
  summary: inquiry.summary,
  key_symptoms: inquiry.key_symptoms,
  attention_points: inquiry.attention_points,
  recommended_tests: inquiry.recommended_tests,
  client_name: inquiry.client_name,
  chat_id: inquiry.chat_id,
  language: inquiry.language
};

const d = $('Match Doctor').first().json;

const urgencyEmoji = {
  'high': '🔴', 'medium': '🟡', 'low': '🟢'
};

const text = `📋 Новое обращение\n\n` +
  `👤 Пациент: ${d.client_name}\n` +
  `📁 Направление: ${d.direction}\n` +
  `${urgencyEmoji[d.urgency] || '⚪'} Срочность: ${d.urgency}\n` +
  `⚖️ Сложность: ${d.severity}\n\n` +
  `📝 Описание:\n${d.summary}\n\n` +
  `🔍 Ключевые симптомы: ${d.key_symptoms}\n\n` +
  `⚠️ Обратить внимание: ${d.attention_points}\n\n` +
  `🔬 Рекомендуемые обследования: ${d.recommended_tests}\n\n` +
  `ID: ${d.inquiry_id}`;

const keyboard = {
  inline_keyboard: [
    [
      { text: '✅ Подтвердить приём', callback_data: `confirm_${d.inquiry_id}` },
      { text: '❓ Запросить инфо', callback_data: `request_${d.inquiry_id}` }
    ],
    [
      { text: '🔄 Перенаправить', callback_data: `reassign_${d.inquiry_id}` },
      { text: '❌ Отклонить', callback_data: `decline_${d.inquiry_id}` }
    ]
  ]
};

return {
  send_body: JSON.stringify({
    chat_id: d.doctor_telegram_id,
    text: text,
    reply_markup: keyboard
  }),
  patient_chat_id: d.chat_id,
  doctor_name: d.doctor_name,
  language: d.language
};

const input = $('Check Input Type').first().json;
const data = input.callback_data || '';

// Формат: confirm_INQ-xxx, request_INQ-xxx, reassign_INQ-xxx, decline_INQ-xxx
const parts = data.split('_');
const action = parts[0]; // confirm, request, reassign, decline
const inquiryId = parts.slice(1).join('_'); // INQ-202607...

return {
  action: action,
  inquiry_id: inquiryId,
  callback_id: input.callback_id,
  message_id: input.message_id,
  doctor_chat_id: input.chat_id,
  doctor_name: input.user_name
};

const cb = $('Parse Callback Data').first().json;
const inq = $('Get Inquiry for Confirm').first().json;

const answerBody = JSON.stringify({
  callback_query_id: cb.callback_id,
  text: 'Приём подтверждён'
});

const editBody = JSON.stringify({
  chat_id: cb.doctor_chat_id,
  message_id: parseInt(cb.message_id),
  text: `✅ ПОДТВЕРЖДЕНО\n\n` +
    `Пациент: ${inq.client_name}\n` +
    `Направление: ${inq.direction}\n` +
    `Срочность: ${inq.urgency}\n\n` +
    `${inq.summary}\n\n` +
    `Подтверждено: ${cb.doctor_name}`
});

const notifyBody = JSON.stringify({
  chat_id: inq.client_telegram_id,
  text: `✅ Врач ${cb.doctor_name} подтвердил ваш приём.\n\n` +
    `Направление: ${inq.direction}\n` +
    `Рекомендуемые обследования: ${inq.recommended_tests}\n\n` +
    `Ожидайте информацию о дате и времени.`
});

return {
  answer_body: answerBody,
  edit_body: editBody,
  notify_body: notifyBody
};

const cb = $('Parse Callback Data').first().json;
const inq = $('Get Inquiry for Reassign').first().json;
const assignments = $('Get All Assignments').all();
const doctors = $('Get Doctors for Reassign').all();

// Собираем ID врачей, которые уже отклонили или получали эту заявку
const excludeIds = assignments
  .filter(r => r.json.inquiry_id === cb.inquiry_id)
  .map(r => r.json.doctor_id);
excludeIds.push(cb.doctor_chat_id); // текущий врач тоже

const direction = inq.direction || 'therapy';

const candidates = doctors
  .filter(r => {
    if (!r.json.doctor_id || r.json.status !== 'active') return false;
    if (excludeIds.includes(r.json.doctor_id)) return false;
    // Не исключаем по telegram_id, исключаем по doctor_id
    const specs = (r.json.specializations || '').split(',').map(s => s.trim());
    return specs.includes(direction);
  })
  .filter(r => {
    const active = parseInt(r.json.active_patients) || 0;
    const max = parseInt(r.json.max_patients) || 999;
    return active < max;
  })
  .sort((a, b) => {
    const aLoad = (parseInt(a.json.active_patients) || 0) / (parseInt(a.json.max_patients) || 1);
    const bLoad = (parseInt(b.json.active_patients) || 0) / (parseInt(b.json.max_patients) || 1);
    return aLoad - bLoad;
  });

const next = candidates[0] || null;

// Формируем answer callback
const answerBody = JSON.stringify({
  callback_query_id: cb.callback_id,
  text: next ? 'Перенаправлено другому врачу' : 'Нет доступных врачей'
});

const editBody = JSON.stringify({
  chat_id: cb.doctor_chat_id,
  message_id: parseInt(cb.message_id),
